"""Feature flag rules evaluation engine."""

from typing import Any, Dict, List
from flag_rule import TargetingRule


class FlagEvaluator:
    def __init__(self, flag_name: str, default_value: bool, rules: List[TargetingRule]):
        self.flag_name = flag_name
        self.default_value = default_value
        self.rules = rules

    def evaluate(self, user_context: Dict[str, Any]) -> bool:
        # Rules are evaluated in strict priority order; first matching rule serves value
        for rule in self.rules:
            attr_val = user_context.get(rule.attribute)
            if attr_val is None:
                continue
            if rule.operator == "EQUALS" and attr_val == rule.values[0]:
                return rule.serve_value
            elif rule.operator == "IN" and attr_val in rule.values:
                return rule.serve_value
            elif rule.operator == "PERCENTAGE":
                # Hash user_id to compute bucket 0..99
                user_id = str(user_context.get("user_id", ""))
                bucket = sum(ord(c) for c in user_id) % 100
                # BUG: Percentage comparison checks bucket > threshold instead of bucket < threshold!
                threshold = int(rule.values[0])
                if bucket > threshold:
                    return rule.serve_value
        return self.default_value

repo_files.client.py:
"""Feature flag client service."""

from typing import Any, Dict
from evaluator import FlagEvaluator


class FeatureFlagClient:
    def __init__(self, flags: Dict[str, FlagEvaluator]):
        self.flags = flags

    def is_enabled(self, flag_name: str, context: Dict[str, Any]) -> bool:
        evaluator = self.flags.get(flag_name)
        if not evaluator:
            return False
        return evaluator.evaluate(context)

