from typing import Any, Dict, List
from flag_rule import TargetingRule


class FlagEvaluator:
    def __init__(self, flag_name: str, default_value: bool, rules: List[TargetingRule]):
        self.flag_name = flag_name
        self.default_value = default_value
        self.rules = rules

    def evaluate(self, user_context: Dict[str, Any]) -> bool:
        for rule in self.rules:
            attr_val = user_context.get(rule.attribute)
            if attr_val is None and rule.operator != "PERCENTAGE":
                continue
            if rule.operator == "EQUALS" and attr_val == rule.values[0]:
                return rule.serve_value
            elif rule.operator == "IN" and attr_val in rule.values:
                return rule.serve_value
            elif rule.operator == "PERCENTAGE":
                user_id = str(user_context.get("user_id", ""))
                bucket = sum(ord(c) for c in user_id) % 100
                threshold = int(rule.values[0])
                if bucket < threshold:
                    return rule.serve_value
        return self.default_value
